  // Capability Lab (diagnostic / experimental)
  'settings.capabilityLab.title': '⚠️ Capability Lab (Diagnostic)',
  'settings.capabilityLab.matrix.title': 'Capability Matrix',
  'settings.capabilityLab.matrix.description': 'Read-only matrix showing SDK parity status for each Claude Code capability. Runtime Proof updates after live diagnostic calls.',
  'settings.capabilityLab.history.title': 'JSONL History Browser (Read-Only)',
  'settings.capabilityLab.history.description': 'Browse Claude Code JSONL messages and run diagnostic store only import, mirror, and readback probes. No stable delete or restore operations are provided.',
  'settings.capabilityLab.subagents.title': 'Subagent Browser (Read-Only)',
  'settings.capabilityLab.subagents.description': 'List and inspect subagent transcripts. Uses listSubagents() and getSubagentMessages(). Read-only — no write operations.',
  'settings.capabilityLab.rewind.title': 'Rewind Dry-Run Preview',
  'settings.capabilityLab.rewind.description': 'Preview what file checkpoint rewind would do. Dry-run only — no actual file restore button is provided. Requires an active checkpoint-enabled runtime.',
  'settings.capabilityLab.structured.title': 'Structured Output Playground (Diagnostic)',
  'settings.capabilityLab.structured.description': 'Diagnostic surface for structured output. Not integrated into the normal chat UI. Probes recent sessions for structured output data.',
  'settings.capabilityLab.fork.title': 'Fork Session Diagnostic (Diagnostic)',
  'settings.capabilityLab.fork.description': 'Provider-owned diagnostic probe for Claude Code forkSession(). Select a session and fork it. The forked session id and title are shown as diagnostic output. Not a stable product surface.',
  'settings.capabilityLab.resume.title': 'Resume Session Diagnostic (Diagnostic)',
  'settings.capabilityLab.resume.description': 'Provider-owned diagnostic probe for Claude Code SDK resume. Select a session and run a diagnostic prompt resumed from that session. The resulting session id and a short output preview are shown as diagnostic output. Not stable resume-at productization.',
  'settings.capabilityLab.sessionDetail.title': 'Session Detail Inspection (Diagnostic)',
  'settings.capabilityLab.sessionDetail.description': 'Provider-owned diagnostic probe for getSession(). Select a session and inspect its raw detail. Shows sessionId, summary, lastModified, and other available fields as diagnostic output. Not a stable product surface — does not represent a cross-backend session object contract.',
  'settings.capabilityLab.backendRouting.title': 'Backend Routing Verification (Diagnostic)',
  'settings.capabilityLab.backendRouting.description': 'Verifies the backend routing infrastructure. Shows the active backend, registered adapters, and conversation backend distribution. Exercises listSessions() and getSession() through the provider-owned routing path. Diagnostic-only: the routing layer is internal infrastructure that enables stable downstream features (session browser, resume, fork, title read), but there is no standalone "Backend Routing" product surface.',
  'settings.capabilityLab.discovery.title': 'Discovery & Status',
  'settings.capabilityLab.discovery.description': 'Status overview for hooks, plugins, skills, agents, and other SDK features. No authoring UI — discovery/status only.',
  'settings.capabilityLab.diagnosticStreamControls.title': 'Diagnostic Stream Controls',
  'settings.capabilityLab.diagnosticStreamControls.description': 'Toggle diagnostic-only SDK stream flags. These controls affect diagnostic probes and stream logs only; they do not change stable chat behavior.',
  'settings.capabilityLab.proofs.continue.button': 'Run Continue Proof',
  'settings.capabilityLab.proofs.continue.running': 'Running continue probe (same session id + nonce recall required for pass)…',
  'settings.capabilityLab.proofs.continue.title': 'Continue Proof',
  'settings.capabilityLab.proofs.continue.boundary': '⚠️ Diagnostic-only — remains diagnostic with explicit blockers: (1) The adapter already maintains ordinary conversation continuity automatically; no user action is needed. (2) continue: true is an implicit "most recent conversation in this directory" flag that conflicts with the adapter\'s explicit per-conversation session tracking. (3) All real user needs are already covered by existing stable surfaces: ordinary chat (auto-continues), Backend Session Browser (resume any session), and Fork Session (branch from any message). (4) Exposing this as a user control would add non-determinism without value.',
  'settings.capabilityLab.proofs.continue.seedSession': 'Seed session: {{sessionId}}',
  'settings.capabilityLab.proofs.continue.continueSession': 'Continue session: {{sessionId}}',
  'settings.capabilityLab.proofs.continue.sessionIdsMatch': 'Session ids match: {{status}}',
  'settings.capabilityLab.proofs.continue.nonceRecalled': 'Nonce recalled: {{status}}',
