  'settings.capabilityLab.proofs.continue.status.no': '✗ no',
  'settings.capabilityLab.proofs.continue.pass': '✓ Pass — session ids match and nonce recalled. SDK continue semantics verified.',
  'settings.capabilityLab.proofs.continue.fail': '✗ Fail — {{error}}',
  'settings.capabilityLab.proofs.continue.defaultError': 'session ids mismatch or nonce not recalled',
  'settings.capabilityLab.proofs.continue.threw': 'Continue proof failed: {{error}}',
  'settings.capabilityLab.proofs.resumeSessionAt.button': 'Run Resume Session At Position Proof',
  'settings.capabilityLab.proofs.resumeSessionAt.running': 'Running resumeSessionAt probe (same session id + alpha nonce recall required for pass)...',
  'settings.capabilityLab.proofs.resumeSessionAt.title': 'Resume Session At Position Proof',
  'settings.capabilityLab.proofs.resumeSessionAt.boundary': '⚠️ Diagnostic-only — remains diagnostic with explicit blockers: (1) Fork Session already provides a stable "branch from here" surface; resumeSessionAt mutates existing session state in-place instead of creating a clean branch. (2) No coherent UX path: users cannot meaningfully distinguish "rewind to here" from "fork from here" in the existing conversation model. (3) In-place session truncation conflicts with the plugin\'s append-only conversation history model and would cause UI/state divergence. (4) The adapter already explicitly guards resumeSessionAt behind a diagnostic-only flag to prevent accidental stable usage.',
  'settings.capabilityLab.proofs.resumeSessionAt.sessionId': 'Session: {{sessionId}}',
